<script setup>
import { computed } from 'vue'
import { shotVideoPrompt } from '../comic_production.js'
const props=defineProps({shot:Object,plan:Object,disabled:Boolean})
const emit=defineEmits(['change','remove','move'])
const preview=computed(()=>shotVideoPrompt(props.shot,props.plan))
const refs=computed(()=>props.plan.passages.filter(row=>props.shot.sourceIds.includes(row.id)))
const changed=()=>emit('change')
const copy=text=>navigator.clipboard.writeText(text).catch(()=>alert('复制失败，请手动复制'))
function addLine(){props.shot.lines.push({characterId:'',text:'新台词',emotion:''});changed()}
</script>
<template>
  <article class="shot-card" :id="`shot-${shot.id}`">
    <header class="shot-header"><strong>镜头 {{ shot.shot }}</strong><span>{{ Number(shot.duration || 0).toFixed(1) }} 秒 · {{ shot.shotSize }} · {{ shot.camera }}</span><div><button :disabled="disabled" @click="shot.locked=!shot.locked;changed()">{{ shot.locked?'解锁':'锁定' }}</button><button :disabled="disabled || shot.locked" @click="emit('move',-1)">上移</button><button :disabled="disabled || shot.locked" @click="emit('move',1)">下移</button><button :disabled="disabled || shot.locked" @click="emit('remove')">删除</button></div></header>
    <div class="shot-body"><div><h4>画面与动作</h4><p>{{ shot.desc }}</p><h4 v-if="shot.lines.length || shot.dialogue">台词 / 旁白</h4><p v-for="(line,index) in shot.lines" :key="index" class="dialogue"><strong>{{ plan.bible.characters.find(row=>row.id===line.characterId)?.name || '旁白' }}：</strong>{{ line.text }}<small v-if="line.emotion">（{{ line.emotion }}）</small></p><p v-if="!shot.lines.length && shot.dialogue" class="dialogue">{{ shot.dialogue }}</p><div v-if="shot.endState" class="state"><span>结束状态</span>{{ shot.endState }}</div></div><div><div class="prompt-heading"><h4>中文视频提示词</h4><button class="copy-btn" @click="copy(preview)">复制</button></div><textarea class="prompt-textarea" :value="preview" readonly aria-label="中文视频提示词"></textarea></div></div>
    <details class="shot-details"><summary>编辑镜头与连续性</summary>
      <fieldset :disabled="disabled || shot.locked" class="edit-grid" @change="changed">
        <label>时长（秒）<input v-model.number="shot.duration" type="number" min="0.1" max="120" step="0.1" /></label><label>景别<input v-model="shot.shotSize" maxlength="100" /></label><label>运镜<input v-model="shot.camera" maxlength="400" /></label><label>角度<input v-model="shot.angle" maxlength="200" /></label>
        <label>场景<select v-model="shot.sceneId"><option value="">未关联</option><option v-for="row in plan.bible.scenes" :key="row.id" :value="row.id">{{ row.name }}</option></select></label>
        <label>出场人物<select v-model="shot.characterIds" multiple><option v-for="row in plan.bible.characters" :key="row.id" :value="row.id">{{ row.name }}</option></select></label>
        <label class="wide">构图<input v-model="shot.composition" maxlength="1000" /></label><label class="wide">画面与动作<textarea v-model="shot.desc" rows="3" maxlength="5000"></textarea></label>
        <label>光影<textarea v-model="shot.lighting" rows="2" maxlength="1500"></textarea></label><label>转场与匹配<textarea v-model="shot.transition" rows="2" maxlength="1000"></textarea></label><label>起始状态<textarea v-model="shot.startState" rows="2" maxlength="2000"></textarea></label><label>结束状态<textarea v-model="shot.endState" rows="2" maxlength="2000"></textarea></label>
        <label class="wide">音效<input v-model="shot.sfx" maxlength="1000" /></label><label class="wide">原文引用<select v-model="shot.sourceIds" multiple><option v-for="row in plan.passages" :key="row.id" :value="row.id">{{ row.id }} · {{ row.text.slice(0,60) }}</option></select></label>
        <div class="wide lines"><div class="prompt-heading"><h4>台词与说话人</h4><button type="button" @click="addLine">添加台词</button></div><div v-for="(line,index) in shot.lines" :key="index" class="line"><select v-model="line.characterId" aria-label="说话人"><option value="">旁白</option><option v-for="row in plan.bible.characters" :key="row.id" :value="row.id">{{ row.name }}</option></select><input v-model="line.text" aria-label="台词" maxlength="3000" /><input v-model="line.emotion" placeholder="情绪 / 语气" aria-label="台词情绪" maxlength="300" /><button type="button" @click="shot.lines.splice(index,1);changed()">移除</button></div><label v-if="!shot.lines.length">原有非结构化台词<textarea v-model="shot.dialogue" rows="2" maxlength="5000"></textarea></label></div>
        <label class="wide">英文图像提示词<textarea v-model="shot.prompt" rows="3" maxlength="6000"></textarea></label><label class="wide">自定义中文视频提示词（留空则按镜头与设定组合）<textarea v-model="shot.videoPromptOverride" rows="3" maxlength="10000"></textarea></label>
      </fieldset>
      <p v-if="shot.locked" class="editor-note">镜头已锁定。批量编辑或调整前可先解锁。</p>
    </details>
    <details v-if="refs.length" class="shot-details"><summary>查看对应原文（{{ refs.length }} 段）</summary><p v-for="row in refs" :key="row.id" class="source-quote"><strong>{{ row.id }}</strong> {{ row.text }}</p></details>
  </article>
</template>
<style scoped>
.shot-card{border:1px solid var(--border-color);border-radius:8px;background:var(--panel-bg);overflow:hidden;margin-bottom:18px;scroll-margin-top:20px}.shot-header{display:flex;gap:14px;align-items:center;padding:13px 16px;background:var(--surface-subtle);border-bottom:1px solid var(--border-color);font-size:12px}.shot-header strong{color:var(--accent-color)}.shot-header>span{color:var(--text-secondary)}.shot-header>div{margin-left:auto;display:flex;gap:10px}.shot-body{display:grid;grid-template-columns:1fr 1fr;gap:20px;padding:18px}h4{font-size:11px;color:var(--text-secondary);font-weight:500;margin:0 0 10px}p{font-size:13px;line-height:1.8;white-space:pre-wrap;margin:0 0 14px}.dialogue{color:var(--text-primary)}.dialogue small{color:var(--text-secondary)}.prompt-heading{display:flex;align-items:center;justify-content:space-between;gap:10px}.prompt-heading h4{margin:0}.prompt-textarea{width:100%;height:220px;box-sizing:border-box;border:1px solid var(--border-color);border-radius:5px;background:var(--surface-subtle);padding:12px;color:var(--text-primary);font:12px/1.8 inherit;resize:vertical;margin-top:12px}.state{padding:10px;background:var(--surface-subtle);font-size:11px;color:var(--text-secondary);line-height:1.7}.state span{display:block;margin-bottom:4px}.shot-details{padding:13px 18px;border-top:1px solid var(--border-color)}summary{font-size:12px;cursor:pointer;color:var(--text-secondary)}button{border:0;background:none;font-size:11px;color:var(--text-secondary);cursor:pointer}.copy-btn{border:1px solid var(--accent-border);padding:5px 10px;border-radius:4px;color:var(--accent-color);background:var(--accent-bg)}button:disabled{opacity:.4;cursor:not-allowed}.edit-grid{border:0;padding:18px 0 0;margin:0;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.edit-grid label{display:flex;flex-direction:column;gap:7px;font-size:11px;color:var(--text-secondary)}.edit-grid input,.edit-grid select,.edit-grid textarea{box-sizing:border-box;width:100%;min-width:0;border:1px solid var(--border-color);border-radius:4px;padding:9px;background:var(--panel-bg);color:var(--text-primary);font:12px/1.6 inherit}.wide{grid-column:1/-1}.line{display:grid;grid-template-columns:120px 1fr 130px auto;gap:8px;margin:10px 0}.editor-note,.source-quote{font-size:12px;color:var(--text-secondary);margin-top:15px}.source-quote{padding:12px;background:var(--surface-subtle)}@media(max-width:950px){.shot-body{grid-template-columns:1fr}.shot-header{flex-wrap:wrap}.shot-header>div{width:100%;margin-left:0;justify-content:flex-end}}@media(max-width:550px){.edit-grid{grid-template-columns:1fr}.line{grid-template-columns:1fr}.shot-body{padding:14px}}
</style>
